if(s.phase>=7&&s.phase<9&&r<6&&!s.flags.six){s.flags.six=true;if(s.gear&&s.flaps&&s.hook&&s.onspeed&&s.v<150)pass('six','On-speed and configured at 6 DME.');else{if(s.guided)feedback('6 DME passed without a stable landing configuration.',true);else s.mistakes.push({t:s.t,text:'Not stably configured at 6 DME.'});pauseFor('Correct your landing configuration before continuing.','six');}}
