const scrubFields={heading:{min:0,max:359,step:1,coarse:10,key:'th',wrap:true},speed:{min:100,max:400,step:5,coarse:25,key:'tv'},altitude:{min:0,max:15000,step:100,coarse:1000,key:'ta'},rate:{min:500,max:6000,step:500,coarse:1000,key:'rate'}};
