function adjustedSetpoint(id,start,steps,coarse=false){const d=scrubFields[id],v=Math.round(start)+steps*(coarse?d.coarse:d.step);return d.wrap?norm(v):clamp(v,d.min,d.max);}
function canAdjust(id){return !s.arrestment&&!s.finished&&!$(id).disabled&&!(id==='speed'&&s.onspeed);}
function nudgeSetpoint(id,direction,coarse=false){if(!canAdjust(id))return;const raw=$(id).value,start=raw!==''&&Number.isFinite(+raw)?+raw:s[scrubFields[id].key];$(id).value=adjustedSetpoint(id,start,direction,coarse);}
